package sortn

import ovid/io

// TestGoalSortLarge sorts two million pseudo-random values, extremes
// included: the result must be ascending and hold the same values.
func TestGoalSortLarge(io *ovid/io.Cap) i64 {
  var n i64 = 2000000
  var p i64 = ovid/io.Alloc(io, n * 8)
  var x i64 = 88172645463325252
  var sum i64 = 0
  var mix i64 = 0
  var i i64 = 0
  while i < n {
    x = x ^ (x << 13)
    x = x ^ ((x >> 7) & 144115188075855871)
    x = x ^ (x << 17)
    var v i64 = x
    if i % 1000 == 0 {
      v = x % 50
    }
    if i == 7 {
      v = -9223372036854775807 - 1
    }
    if i == 9 {
      v = 9223372036854775807
    }
    store64(p + i * 8, v)
    sum = sum + v
    mix = mix ^ (v * 31 + (v >> 3))
    i = i + 1
  }
  Sort(io, p, n)
  i = 0
  while i < n {
    var v i64 = load64(p + i * 8)
    if i > 0 && load64(p + i * 8 - 8) > v {
      return 1
    }
    sum = sum - v
    mix = mix ^ (v * 31 + (v >> 3))
    i = i + 1
  }
  if sum != 0 || mix != 0 {
    return 2
  }
  if load64(p) != -9223372036854775807 - 1 || load64(p + n * 8 - 8) != 9223372036854775807 {
    return 3
  }
  if Sort(io, p, 0) != 0 || Sort(io, p, 1) != 0 {
    return 4
  }
  return 0
}
